import ghidra.app.script.GhidraScript;import java.nio.file.*;public class ChildRefs extends GhidraScript {public void run()throws Exception{StringBuilder b=new StringBuilder();var it=currentProgram.getListing().getInstructions(true);while(it.hasNext()){var i=it.next();for(var ref:i.getReferencesFrom()){long a=ref.getToAddress().getOffset();if(a>=0x7bfc40L&&a<0x7c2634L){var f=getFunctionContaining(i.getAddress());b.append(ref.getToAddress()+"\t"+i.getAddress()+"\t"+(f==null?"none":f.getEntryPoint())+"\t"+i+"\n");}}}for(String a:new String[]{"00514d30","00514400","005144d0","00514600","00514700","00514920","00511260","00511350"})for(var x:getReferencesTo(toAddr(a))){var f=getFunctionContaining(x.getFromAddress());b.append("call:"+a+"\t"+x.getFromAddress()+"\t"+(f==null?"none":f.getEntryPoint())+"\n");}Files.writeString(Path.of(getScriptArgs()[0]),b.toString());}}
